/* Local-only learning state; no analytics or remote dependencies. */
(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const key='gtstudy-belgic-v1';let state={done:[],notes:{},theme:'light',font:0};
try{state={...state,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{}
const save=()=>{try{localStorage.setItem(key,JSON.stringify(state));if($('#saveStatus'))$('#saveStatus').textContent='已保存到当前浏览器'}catch{if($('#saveStatus'))$('#saveStatus').textContent='浏览器未允许保存；可使用导出备份'}};
function applyPrefs(){document.documentElement.dataset.theme=state.theme;document.documentElement.style.setProperty('--reading',(state.font===1?19:state.font===2?21:matchMedia('(max-width:600px)').matches?16:17)+'px')}
applyPrefs();$('#theme')?.addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';applyPrefs();save()});$('#font')?.addEventListener('click',()=>{state.font=(state.font+1)%3;applyPrefs();save()});
let ticking=false;window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{const h=document.documentElement;const percent=h.scrollHeight===innerHeight?0:100*scrollY/(h.scrollHeight-innerHeight);if($('#scrollProgress'))$('#scrollProgress').style.width=percent+'%';ticking=false});ticking=true}},{passive:true});
const small=()=>matchMedia('(max-width:900px)').matches;
function tocToggle(force){if(small()){const show=force??!document.body.classList.contains('toc-open');document.body.classList.toggle('toc-open',show);$('#tocToggle')?.setAttribute('aria-expanded',String(show));if(show)$('#tocClose')?.focus()}else{const show=force??document.body.classList.contains('toc-hidden');document.body.classList.toggle('toc-hidden',!show);$('#tocToggle')?.setAttribute('aria-expanded',String(show))}}
if($('#tocToggle')){tocToggle(!small());$('#tocToggle').addEventListener('click',()=>tocToggle());$('#tocClose').addEventListener('click',()=>{tocToggle(false);$('#tocToggle').focus()});$('#tocBackdrop').addEventListener('click',()=>tocToggle(false));$$('#toc a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{if(small())tocToggle(false)}));document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&small())tocToggle(false)})}
$$('.city-btn').forEach(b=>b.addEventListener('click',()=>{$$('.city-btn').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$$('.city-detail').forEach(x=>x.hidden=x.id!=='city-'+b.dataset.city)}));
function progress(){$$('.mark-done').forEach(b=>b.setAttribute('aria-pressed',String(state.done.includes(Number(b.dataset.n)))));if($('#learnedCount'))$('#learnedCount').textContent=state.done.length+' / 37 条已标记';if($('#learnedProgress'))$('#learnedProgress').value=state.done.length}
progress();$$('.mark-done').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.n);state.done=state.done.includes(n)?state.done.filter(x=>x!==n):[...state.done,n];progress();save()}));
$$('[data-note]').forEach(t=>{t.value=state.notes[t.dataset.note]||'';t.addEventListener('input',()=>{state.notes[t.dataset.note]=t.value;save()})});
if($('#articleSearch')){const cards=$$('.article-card');const textCache=cards.map(c=>c.textContent.toLowerCase());function filter(){const term=$('#articleSearch').value.trim().toLowerCase(),group=$('#groupFilter').value;let count=0;cards.forEach((c,i)=>{c.hidden=!((!term||textCache[i].includes(term))&&(!group||c.dataset.group===group));if(!c.hidden)count++});$('#searchCount').textContent=`显示 ${count} / 37 条` ;$('#noResults').hidden=count!==0}$('#articleSearch').addEventListener('input',filter);$('#groupFilter').addEventListener('change',filter);$('#resetSearch').addEventListener('click',()=>{$('#articleSearch').value='';$('#groupFilter').value='';filter()});$('#showOriginals').addEventListener('click',()=>{const details=$$('.original'),open=details.some(d=>!d.open);details.forEach(d=>d.open=open);$('#showOriginals').textContent=open?'收起全部原文':'展开全部原文'});$$('a[href^="#article-"]').forEach(a=>a.addEventListener('click',()=>{if($('#articleSearch').value||$('#groupFilter').value){$('#articleSearch').value='';$('#groupFilter').value='';filter()}}))}
const flash=$('#flashData');if(flash){const data=JSON.parse(flash.textContent);let index=0;function show(){const d=data[index];$('#flashIndex').textContent=`第${d.n}条 / 共37条` ;$('#flashQuestion').textContent=d.title;$('#flashAnswer').replaceChildren();const p=document.createElement('p');p.textContent=d.core;const b=document.createElement('b');b.textContent='✧ '+d.memory;$('#flashAnswer').append(p,b);$('#flashAnswer').hidden=true;$('#flashReveal').textContent='显示核心与记忆句';$('#flashReveal').setAttribute('aria-expanded','false')}show();$('#flashPrev').addEventListener('click',()=>{index=(index+36)%37;show()});$('#flashNext').addEventListener('click',()=>{index=(index+1)%37;show()});$('#flashRandom').addEventListener('click',()=>{index=(index+1+Math.floor(Math.random()*36))%37;show()});$('#flashReveal').addEventListener('click',()=>{const show=$('#flashAnswer').hidden;$('#flashAnswer').hidden=!show;$('#flashReveal').textContent=show?'遮盖答案':'显示核心与记忆句';$('#flashReveal').setAttribute('aria-expanded',String(show))})}
const quizzes=[{q:'为什么信条先谈启示，再谈救恩？',o:['因为人的宗教感觉足以决定真理','因为我们必须先知道凭什么认识神','因为教会比圣经更有权威'],a:1,e:'第2—7条先交代认识神的途径和圣经的规范地位；之后的三一、基督与救恩都受此约束。'},{q:'称义与成圣的正确关系是什么？',o:['善行积累到足够多，人才被称义','基督的义是称义根基，更新与善行是必然果子','称义以后不再需要悔改'],a:1,e:'第22—24条区分白白被接纳与生命被更新。信心不以功德称义，却必在爱中结出果子。'},{q:'婴孩领受洗礼意味着什么？',o:['外在水礼保证每位受洗者已重生','恩约记号与教会归属，同时呼唤信心与顺服','婴孩天然无罪，所以可以受洗'],a:1,e:'第34条与海德堡第74问将儿女、圣约和记号联系起来；记号与所表明的救恩不能机械等同。'},{q:'第36条今天怎样负责任地使用？',o:['忽略所有历史修订，称它始终同字','按采用版本释义，结合顺服神与合法治理的边界','推论所有政府命令都绝对正确'],a:1,e:'第36条有明确的历史版本差异；徒5:29所显明的良心界限不能被取消，亦不可把所有重洗派标签为暴力者。'},{q:'为何要同时保留三项联合信条？',o:['分别提供三套互不兼容的救恩','一份整体认信、一份牧养教导、一份澄清争论','只有多特信经才有正式权威'],a:1,e:'三份文件形成于不同场景，整体、训练与争议辨析互相补足，共同从属于圣经。'},{q:'怎样理解末日按行为审判？',o:['善行取代基督成为赦罪根基','神公开显明人的生命，善行见证活信心','信徒将完全不面对基督的审判'],a:1,e:'第37条须与第22—24条同读：基督是救恩根基，行为显明信心的真实，并非另一条自救道路。'}];
if($('#quiz'))quizzes.forEach((q,i)=>{const box=document.createElement('article');box.className='quiz-item';const h=document.createElement('h4');h.textContent=(i+1)+'. '+q.q;const opts=document.createElement('div');opts.className='quiz-options';const feedback=document.createElement('p');feedback.className='quiz-feedback';feedback.hidden=true;feedback.setAttribute('role','status');q.o.forEach((txt,j)=>{const b=document.createElement('button');b.type='button';b.textContent=String.fromCharCode(65+j)+' · '+txt;b.addEventListener('click',()=>{feedback.hidden=false;feedback.classList.toggle('wrong',j!==q.a);feedback.textContent=(j===q.a?'✓ 正确。':'再想一想。')+q.e;Array.from(opts.children).forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});opts.append(b)});box.append(h,opts,feedback);$('#quiz').append(box)});
$('#exportNotes')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify({format:key,date:new Date().toISOString(),state},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='belgic-study-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});
$('#importNotes')?.addEventListener('change',async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>2e6)throw Error('文件过大');const d=JSON.parse(await f.text());if(d.format!==key||!d.state||!Array.isArray(d.state.done)||!d.state.notes)throw Error('备份格式不符');state.done=[...new Set(d.state.done.filter(n=>Number.isInteger(n)&&n>=1&&n<=37))];state.notes=Object.fromEntries(Object.entries(d.state.notes).filter(([k,v])=>/^([1-9]|[12][0-9]|3[0-7])$/.test(k)&&typeof v==='string').map(([k,v])=>[k,v.slice(0,50000)]));save();progress();$$('[data-note]').forEach(t=>t.value=state.notes[t.dataset.note]||'');$('#saveStatus').textContent='备份已导入；原有同条笔记已由备份替换'}catch(err){$('#saveStatus').textContent='导入失败：'+err.message}ev.target.value=''});
const originalData=$('#originalData');if(originalData){const data=JSON.parse(originalData.textContent),select=$('#docSelect');let selected='apostles';const status=msg=>$('#readerStatus').textContent=msg;function switchDoc(){selected=select.value;$$('.document').forEach(d=>d.hidden=d.dataset.doc!==selected);if('speechSynthesis'in window)speechSynthesis.cancel();const u=new URL(location.href);u.searchParams.set('doc',selected);history.replaceState({},'',u);status('');if($('#readerMask').getAttribute('aria-pressed')==='true')mask(false)}function mask(on){document.body.classList.toggle('masked',on);$('#readerMask').setAttribute('aria-pressed',String(on));$('#readerMask').textContent=on?'显示全部正文':'遮盖正文 · 背诵';$$('.reader-passage').forEach(p=>{p.classList.remove('revealed');p.setAttribute('aria-expanded',String(!on));p.querySelector('.original-text').setAttribute('aria-hidden',String(on))})}const requested=new URLSearchParams(location.search).get('doc');if(data.documents.some(d=>d.key===requested))select.value=requested;switchDoc();select.addEventListener('change',switchDoc);$('#readerMask').addEventListener('click',()=>mask(!document.body.classList.contains('masked')));$$('.reader-passage').forEach(p=>{const toggle=()=>{if(!document.body.classList.contains('masked'))return;p.classList.toggle('revealed');const show=p.classList.contains('revealed');p.setAttribute('aria-expanded',String(show));p.querySelector('.original-text').setAttribute('aria-hidden',String(!show))};p.addEventListener('click',toggle);p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}})});const text=()=>{const d=data.documents.find(d=>d.key===selected);return d.title+'\n\n'+d.sections.map(s=>(d.sections.length>1?s.title+'\n\n':'')+s.text).join('\n\n')};$('#readerCopy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text());status('当前全文已复制')}catch{status('浏览器未允许复制，请选择正文手动复制')}});$('#readerPrint').addEventListener('click',()=>window.print());$('#readerSpeak').addEventListener('click',()=>{if(!('speechSynthesis'in window)){status('此设备未提供语音朗读');return}speechSynthesis.cancel();const d=data.documents.find(d=>d.key===selected);const parts=d.sections.flatMap(s=>(s.title+'。'+s.text).match(/[^。！？\n]+[。！？]?/g)||[]);let i=0;function next(){if(i>=parts.length){status('朗读结束');return}const u=new SpeechSynthesisUtterance(parts[i++]);u.lang='zh-CN';u.rate=.88;u.onend=next;u.onerror=()=>status('朗读中止：请检查设备中文语音');speechSynthesis.speak(u)}status('正在使用设备语音朗读；可随时停止');next()});$('#readerStop').addEventListener('click',()=>{if('speechSynthesis'in window)speechSynthesis.cancel();status('朗读已停止')});window.addEventListener('pagehide',()=>{if('speechSynthesis'in window)speechSynthesis.cancel()})}
})();
